<?php require __DIR__.'/app/bootstrap.php';$ids=array_map('intval',$_SESSION['wishlist']??[]);$items=[];if($ids){$marks=implode(',',array_fill(0,count($ids),'?'));$s=db()->prepare("SELECT * FROM products WHERE status='active' AND id IN ($marks)");$s->execute($ids);$items=$s->fetchAll();}$pageTitle='Wishlist — NEXT TECH';require __DIR__.'/includes/header.php';?><section class="page-intro"><span class="eyebrow">SAVED ITEMS</span><h1>Wishlist</h1></section><?php if($items):?><div class="product-grid"><?php foreach($items as $p):?><article class="product-card"><a href="<?=e(url('product.php?slug='.rawurlencode($p['slug'])))?>"><div class="product-image"><?php if($p['image']):?><img src="<?=e(url('uploads/products/'.$p['image']))?>" alt="<?=e($p['name'])?>"><?php else:?><span>◇</span><?php endif;?></div><h3><?=e($p['name'])?></h3></a><p class="price"><?=money($p['price'])?></p></article><?php endforeach;?></div><?php else:?><p class="empty-state">Your wishlist is empty. Wishlist saving will be enabled in a later phase.</p><?php endif;?><?php require __DIR__.'/includes/footer.php';?>